<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { papersApi, tasksApi } from '../services/api'
import { fields, verdicts, dateText } from '../services/labels'
import { isActive } from '../services/jobs'
import BaseDialog from '../components/BaseDialog.vue'
import SourcesPanel from '../components/SourcesPanel.vue'
import AnalysisPanel from '../components/AnalysisPanel.vue'
import ReportPanel from '../components/ReportPanel.vue'
import JobSummary from '../components/JobSummary.vue'
import StatusBadge from '../components/StatusBadge.vue'
const props=defineProps({jobs:Object,notify:Function,paperRevision:Number})
const emit=defineEmits(['source','jobs'])
const tasks=ref([]),papers=ref([]),selectedId=ref(null),links=ref([]),tab=ref('papers'),loading=ref(false),detailLoading=ref(false),busy=ref(''),error=ref(''),analysis=ref(null),review=ref(null),revisions=ref(null),versions=ref([]),versionDetail=ref(null),answer=ref(null),matches=ref([]),question=ref(''),topK=ref(5),paperChoice=ref(''),creating=ref(false),deleting=ref(false),formError=ref(''),confirmation=ref(null)
const form=reactive({title:'',question:''})
const selected=computed(()=>tasks.value.find(x=>x.id===selectedId.value))
const choices=computed(()=>papers.value.filter(p=>!links.value.some(link=>link.paper_id===p.id)))
const reportJob=computed(()=>props.jobs.latest('report',selectedId.value))
const locked=computed(()=>!!busy.value||detailLoading.value||isActive(reportJob.value?.job))
let sequence=0
const elapsed=ref(0)
let waitingController=null, waitTimer=null
const canStopWaiting=computed(()=>['answer','analysis','review','revise','adopt'].includes(busy.value))
function stopWaiting(){waitingController?.abort()}
onUnmounted(()=>{waitingController?.abort();if(waitTimer)clearInterval(waitTimer)})
async function refresh(){loading.value=true;error.value='';try{const [t,p]=await Promise.all([tasksApi.list(),papersApi.list()]);tasks.value=t;papers.value=p;if(selectedId.value&&!t.some(x=>x.id===selectedId.value))selectedId.value=null;if(!selectedId.value&&t.length)await choose(t[0].id);else if(selectedId.value)await choose(selectedId.value)}catch(cause){error.value=cause.message}finally{loading.value=false}}
async function choose(id){if(busy.value)return;selectedId.value=id;const token=++sequence;detailLoading.value=true;error.value='';analysis.value=null;review.value=null;revisions.value=null;answer.value=null;matches.value=[];versionDetail.value=null;links.value=[];versions.value=[];paperChoice.value=''
 const results=await Promise.allSettled([tasksApi.links(id),tasksApi.analysis(id),tasksApi.review(id),tasksApi.versions(id)])
 if(token!==sequence)return
 const targets=[links,analysis,review,versions];const messages=[]
 results.forEach((result,index)=>{if(result.status==='fulfilled')targets[index].value=result.value;else messages.push(result.reason.message)})
 error.value=[...new Set(messages)].join('；');detailLoading.value=false
}
async function createTask(){if(busy.value)return;formError.value='';if(!form.title.trim()||!form.question.trim()){formError.value='请填写任务名称和研究问题。';return}busy.value='create';let created
 try{created=await tasksApi.create({title:form.title.trim(),question:form.question.trim()});tasks.value.push(created);creating.value=false;form.title='';form.question='';props.notify('研究任务已创建。')}catch(cause){formError.value=cause.message}finally{busy.value=''}if(created)await choose(created.id)
}
async function act(name,operation){if(locked.value)return;busy.value=name;error.value='';elapsed.value=0;waitingController=new AbortController();const started=Date.now();waitTimer=setInterval(()=>{elapsed.value=Math.floor((Date.now()-started)/1000)},1000);try{await operation()}catch(cause){error.value=cause.message;props.notify(cause.message,'error')}finally{clearInterval(waitTimer);waitTimer=null;waitingController=null;busy.value=''}}
async function addPaper(){const id=Number(paperChoice.value);if(!id)return;await act('link',async()=>{await tasksApi.link(selectedId.value,id);links.value=await tasksApi.links(selectedId.value);paperChoice.value='';analysis.value=null;review.value=null;revisions.value=null;tasks.value=await tasksApi.list();props.notify('论文已关联，请重新分析。')})}
async function unlink(paperId){await act('unlink',async()=>{await tasksApi.unlink(selectedId.value,paperId);links.value=await tasksApi.links(selectedId.value);analysis.value=null;review.value=null;revisions.value=null;tasks.value=await tasksApi.list();props.notify('论文已移出任务，原PDF仍保留，请重新分析。')})}
async function ask(mode){if(!question.value.trim())return;await act(mode,async()=>{if(mode==='answer')answer.value=await tasksApi.answer(selectedId.value,question.value.trim(),Number(topK.value),waitingController.signal);else matches.value=await tasksApi.search(selectedId.value,question.value.trim(),Number(topK.value))})}
async function analyze(){await act('analysis',async()=>{analysis.value=await tasksApi.analyze(selectedId.value,waitingController.signal);review.value=null;revisions.value=null;props.notify('分析已保存。')})}
async function runReview(){await act('review',async()=>{review.value=await tasksApi.runReview(selectedId.value,waitingController.signal);revisions.value=null;props.notify('审校已保存。')})}
async function revise(){await act('revise',async()=>{revisions.value=await tasksApi.revise(selectedId.value,waitingController.signal);props.notify('修订建议已生成，请查看复审结果。')})}
async function generateReport(){await act('report',async()=>{try{const job=await tasksApi.report(selectedId.value);props.jobs.track('report',selectedId.value,job);props.notify(`报告作业 ${job.id} 已排队。`)}catch(cause){if(cause.jobId)props.jobs.track('report',selectedId.value,{id:cause.jobId,status:'queued'});throw cause}})}
async function showVersion(version){await act('version',async()=>{versionDetail.value=await tasksApi.version(selectedId.value,version.id)})}
async function confirmMutation(){const operation=confirmation.value;if(!operation)return;await act(operation.type,async()=>{if(operation.type==='restore'){const result=await tasksApi.restore(selectedId.value,operation.id,analysis.value);analysis.value=result.analysis;review.value=null;revisions.value=null;versions.value=await tasksApi.versions(selectedId.value);versionDetail.value=null;props.notify('已恢复历史分析，并保存新的历史记录。')}else{const result=await tasksApi.adopt(selectedId.value,analysis.value,operation.revision,waitingController.signal);analysis.value=result.analysis;review.value=null;revisions.value=null;versions.value=await tasksApi.versions(selectedId.value);props.notify('陈述已移动到证据备注，旧审校已清除。')}confirmation.value=null})}
async function deleteTask(){await act('delete',async()=>{await tasksApi.remove(selectedId.value);tasks.value=tasks.value.filter(x=>x.id!==selectedId.value);selectedId.value=null;deleting.value=false;props.notify('任务已删除，论文和PDF保留。')});if(!selectedId.value&&tasks.value.length)await choose(tasks.value[0].id)}
watch(()=>props.paperRevision,async()=>{try{papers.value=await papersApi.list()}catch{}})
onMounted(refresh)
</script>
<template>
 <header class="page-head"><div><p class="eyebrow">研究流程 / RESEARCH</p><h1>围绕问题，组织证据</h1><p class="muted">关联论文，检索原文，分析、审校并生成对比报告。</p></div><button class="primary" :disabled="!!busy" @click="formError='';creating=true">＋ 创建任务</button></header>
 <div class="research-layout"><aside class="task-list"><div class="row between"><h3>研究任务 <small>{{tasks.length}}</small></h3><button class="text-button" :disabled="loading||!!busy" @click="refresh">刷新</button></div><p v-if="loading&&!tasks.length" class="empty">读取中…</p><button v-for="task in tasks" :key="task.id" class="task-choice" :class="{selected:task.id===selectedId}" :disabled="!!busy" @click="choose(task.id)"><small>任务 {{task.id}}</small><strong>{{task.title}}</strong><span>{{task.question}}</span></button><p v-if="!tasks.length&&!loading" class="empty">创建你的第一个研究任务。</p></aside>
 <section class="task-workspace"><p v-if="error" class="notice error" role="alert">{{error}}</p><template v-if="selected"><div class="row between task-title"><div><span class="eyebrow">TASK / {{selected.id}}</span><h2>{{selected.title}}</h2><p class="prose">{{selected.question}}</p></div><button class="text-button danger" :disabled="locked" @click="deleting=true">删除任务</button></div>
 <p v-if="selected.status==='stale'" class="notice warning">关联论文已变化，旧分析已过期。请到“分析与审校”重新生成分析。</p><nav class="tabs" aria-label="任务功能"><button v-for="(label,key) in {papers:'关联论文',answer:'问答与检索',analysis:'分析与审校',versions:'历史版本',report:'对比报告'}" :key="key" :class="{active:tab===key}" @click="tab=key">{{label}}</button></nav><p v-if="busy" class="notice loading" role="status">正在{{{link:'关联论文',unlink:'移除关联',answer:'生成回答',search:'检索原文',analysis:'分析论文',review:'审校分析',revise:'修订并复审',report:'提交报告',version:'读取版本',restore:'恢复版本',adopt:'核验并采纳',delete:'删除任务'}[busy]||'处理'}}，请等待完成。已等待 {{elapsed}} 秒。生成类操作可能需要数分钟。<button v-if="canStopWaiting" class="text-button" @click="stopWaiting">停止等待</button><span v-if="canStopWaiting">停止等待不会取消服务端操作，请刷新核对结果后再提交。</span></p><p v-if="detailLoading" class="empty">读取任务资料…</p>
 <div v-else-if="tab==='papers'"><p class="muted">先在论文库完成后台准备，再关联到任务。关联变化后，请重新分析以更新结果。</p><div class="toolbar"><select v-model="paperChoice" aria-label="选择关联论文" :disabled="locked"><option value="">选择一篇论文</option><option v-for="paper in choices" :key="paper.id" :value="paper.id">{{paper.id}} · {{paper.title}}</option></select><button class="primary" :disabled="locked||!paperChoice" @click="addPaper">关联论文</button></div><article v-for="link in links" :key="link.id" class="linked-paper"><div><small>论文 {{link.paper_id}}</small><h3>{{link.paper.title}}</h3><p class="muted">{{link.paper.author}} · {{link.paper.year}}</p></div><div class="actions"><button @click="emit('source',{paper_id:link.paper_id,paper_title:link.paper.title,page_number:1})">查看正文</button><button class="text-button danger" :disabled="locked" @click="unlink(link.paper_id)">移出任务</button></div></article><p v-if="!links.length" class="empty">这个任务还没有关联论文。</p></div>
 <div v-else-if="tab==='answer'"><form @submit.prevent="ask('answer')"><fieldset :disabled="locked"><label>向任务论文提问<textarea v-model="question" required maxlength="2000" rows="3" placeholder="例如：这些研究如何评估语义缓存的命中质量？"></textarea></label><div class="toolbar"><label class="inline-label">召回条数<input v-model.number="topK" type="number" min="1" max="20" required /></label><button type="button" :disabled="!question.trim()||!links.length" @click="ask('search')">只检索原文</button><button class="primary" type="submit" :disabled="!links.length">生成回答</button></div><p class="hint">生成回答会将相关论文片段发送给 DeepSeek；只检索原文使用本地向量模型。</p></fieldset></form><section v-if="answer" class="result-box"><h3>回答</h3><p class="prose">{{answer.answer}}</p><SourcesPanel :sources="answer.sources" @source="emit('source',$event)" /></section><section v-if="matches.length"><h3>检索原文</h3><article v-for="match in matches" :key="match.chunk_id" class="quote-box"><button class="text-button" @click="emit('source',match)">{{match.paper_title}} · 第 {{match.page_number}} 页</button><p class="prose">{{match.text}}</p><small class="muted">相似度 {{Number(match.score).toFixed(3)}} · 文本块 {{match.chunk_id}}</small></article></section></div>
 <div v-else-if="tab==='analysis'"><div class="toolbar"><button class="primary" :disabled="locked||!links.length" @click="analyze">{{analysis?'重新分析':'生成分析'}}</button><button :disabled="locked||!analysis" @click="runReview">审校分析</button><button :disabled="locked||!review" @click="revise">修订并复审</button></div><p class="hint">分析、审校和修订使用 DeepSeek。重新分析会更新任务结果；采纳和恢复操作会保留版本。</p><AnalysisPanel v-if="analysis" :analysis="analysis" @source="emit('source',$event)" /><p v-else class="empty">先关联并准备论文，再生成结构化分析。</p><section v-if="review"><h3>审校结果</h3><article v-for="(item,index) in review.items" :key="index" class="review-item"><div class="row"><span class="badge" :class="item.verdict==='supported'?'ok':'unknown'">{{verdicts[item.verdict]}}</span><small class="muted">{{fields[item.field]||item.field}}</small></div><p class="prose">{{item.claim}}</p><p class="muted">{{item.reason}}</p><small>引用资料：{{item.source_numbers.join('、')||'无'}}</small></article><p v-if="!review.items.length" class="empty">暂无可展示的审校条目。</p></section><section v-if="revisions"><h3>修订建议（{{revisions.items.length}} 条）</h3><p class="muted">建议不会自动覆盖原分析。当前采纳接口支持将合格陈述移动到证据备注。</p><article v-for="(item,index) in revisions.items" :key="index" class="review-item"><small>{{fields[item.revision.field]||item.revision.field}}</small><p class="muted">原陈述：{{item.revision.original_claim}}</p><p class="prose">建议：{{item.revision.revised_claim}}</p><p>{{item.revision.reason}}</p><div class="row"><span class="badge" :class="item.review.verdict==='supported'?'ok':'unknown'">{{verdicts[item.review.verdict]}}</span><span class="badge">{{verdicts[item.field_check.verdict]}}</span></div><p class="muted">{{item.review.reason}}</p><button v-if="item.field_move?.ready && ['methods','experiments','conclusions','limitations'].includes(item.revision.field)" :disabled="locked" @click="confirmation={type:'adopt',revision:item.revision}">移动到证据备注</button><details v-if="item.split_checks?.length"><summary>查看拆分建议</summary><p v-for="(split,i) in item.split_checks" :key="i" class="prose">{{fields[split.item.field]}}：{{split.item.claim}}（{{split.ready?'检查通过':'需要核对'}}）</p></details></article><details v-if="revisions.skipped_items?.length"><summary>未生成修订的条目（{{revisions.skipped_items.length}} 条）</summary><p v-for="(item,i) in revisions.skipped_items" :key="i">{{item.claim}} · {{verdicts[item.verdict]}}</p></details></section></div>
 <div v-else-if="tab==='versions'"><p class="muted">历史记录保存采纳或恢复操作前后的分析。恢复目标是该记录的“修改前分析”。</p><article v-for="version in versions" :key="version.id" class="version-row"><div><strong>版本记录 {{version.id}}</strong><p>{{version.reason}}</p><small>{{dateText(version.created_at)}}</small></div><button :disabled="locked" @click="showVersion(version)">查看变化</button></article><p v-if="!versions.length" class="empty">暂无版本记录。首次采纳或恢复后会产生记录。</p><section v-if="versionDetail" class="result-box"><div class="row between"><h3>版本记录 {{versionDetail.id}}</h3><button :disabled="locked||!analysis" @click="confirmation={type:'restore',id:versionDetail.id}">恢复修改前分析</button></div><details open><summary>修改前分析</summary><AnalysisPanel :analysis="versionDetail.previous_analysis" @source="emit('source',$event)" /></details><details><summary>修改后分析</summary><AnalysisPanel :analysis="versionDetail.updated_analysis" @source="emit('source',$event)" /></details></section></div>
 <div v-else><div class="toolbar"><button class="primary" :disabled="locked||!analysis||links.length<2" @click="generateReport">后台生成对比报告</button><button @click="emit('jobs')">打开作业与报告</button></div><p class="hint">需要已保存的分析和至少两篇关联论文。报告生成、补证和审校使用 DeepSeek。作业完成后还要检查报告是否通过审校。</p><JobSummary :item="reportJob" /><ReportPanel :result="reportJob?.job?.result" @source="emit('source',$event)" /></div>
 </template><p v-else class="empty">从左侧选择任务，或创建一个新任务。</p></section></div>
 <BaseDialog :open="creating" title="创建研究任务" @close="!busy&&(creating=false)"><form @submit.prevent="createTask"><fieldset :disabled="!!busy"><label>任务名称<input v-model="form.title" required maxlength="200" /></label><label>研究问题<textarea v-model="form.question" required maxlength="2000" rows="4"></textarea></label><p v-if="formError" class="notice error">{{formError}}</p><div class="actions"><button type="button" @click="creating=false">取消</button><button class="primary" type="submit">创建任务</button></div></fieldset></form></BaseDialog>
 <BaseDialog :open="deleting" title="删除研究任务" @close="!busy&&(deleting=false)"><p>确认删除「{{selected?.title}}」及其分析、报告和作业历史？论文及PDF会保留。</p><template #actions><button :disabled="!!busy" @click="deleting=false">取消</button><button class="danger-button" :disabled="!!busy" @click="deleteTask">确认删除</button></template></BaseDialog>
 <BaseDialog :open="!!confirmation" :title="confirmation?.type==='restore'?'恢复历史分析':'采纳移动建议'" @close="!busy&&(confirmation=null)"><p>{{confirmation?.type==='restore'?'将恢复所选记录的修改前分析，清除旧审校，并创建新的版本记录。':'将核验建议，把陈述移动到证据备注，保留历史并清除旧审校。这一步会调用DeepSeek。'}}确认继续？</p><template #actions><button :disabled="!!busy" @click="confirmation=null">取消</button><button class="primary" :disabled="!!busy" @click="confirmMutation">确认{{confirmation?.type==='restore'?'恢复':'采纳'}}</button></template></BaseDialog>
</template>
